import { readdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';

const root = process.argv[2] ?? 'tmp';
for (const entry of readdirSync(root, { recursive: true }) as string[]) {
  if (entry.endsWith('.log')) rmSync(join(root, entry));
}

